P["AS-211"] = ("方向：马可找回。马星十二宫主逆行、急向问者二宫主合相，月亮居二宫、二逆行星近二宫头——失畜向财宫收拢为复得之象；马所去方向为西（十二宫星座与其主所在星座皆主西，证多从西）。应期以日计：窗口为问后数日内、主坐标十二主与二主合相成之时日。置信中高。",
 "卡面 tradition＝horary。\n依据：大畜失物以十二宫主逆行向二宫主合定复得、星座象限定方向。R61-REV1：方位断项指针2项同指西，保留方位级；应期日档二路同点。", 0.66, F)
P["AS-212"] = ("方向：非巫术所祟（not bewitched），乃自然之病。虽月亮将冲土星、二星分居六/十二宫起疑，然命宫、命主、月亮皆不受十二宫主所克为决定性反证；月亮冲土星后转应命主（在上半天向天顶上升），主病势有向愈之机。应期以周/月计：转机窗口为问后数周、主坐标月亮应命主成相之时。置信中高。",
 "卡面 tradition＝horary。\n依据：巫祟占之成文否证——命与月不受十二主 affliction 则非巫。R61-REV1：应期初推月亮行度（先冲土后应命主）、复推命主上升向meridian核之，同指先滞后转窗；无具体断项需降档。", 0.66, F)
P["AS-213"] = ("方向：逃犯往东而去，且将被抓回。十二宫头射手与其主木星居狮子、天象限与月亮星座四证一致向东；月亮近命宫、离木星三合将冲太阳（两星皆居角宫），主行踪显露、官面（太阳）截获。应期以日计：窗口为逃后数日内、主坐标月冲太阳成相之日。置信中高。",
 "卡面 tradition＝horary。\n依据：逃犯占以十二宫主定位、方位四证合一定东；月亮应太阳居角主被获。R61-REV1：方位断项指针≥2同向保留；应期日档二路同点数日内。", 0.66, F)
P["AS-215"] = ("方向：Essex此次西征不利、无功且损军失誉，其终局凶。命主土星 peregrine 入陷居二宫、月亮居 detriment、南交居命宫、福点受七宫主（敌方星）支配、月亮将四分火星（二/九宫主，主其资财援兵与行程）——事件盘诸证同主败。应期以月计：凶应在出征后数月内，窗口为1644年夏秋之交、主坐标其军困降所在的初秋。置信高。",
 "卡面 tradition＝horary。\n依据：事件盘（event figure）以出征时刻命主与福点状态定全程成败。R61-REV1：应期月档，初推月亮四分火星行度、复推以出征后行程尺度核为夏秋窗；无确日断项。", 0.72, F)
# ---------- AS modern public predictions (no chart attachments: sparse input) ----------
P["AS-301"] = ("方向：2020年世界局势以突发公共卫生危机开局并主导全年——年初疫病自亚洲暴发、春间扩散全球，各国封锁、经济急挫、死亡攀升；年中疫情反复、年末疫苗带来转机而未终局。逐月尺度：1-3月暴发扩散、4-6月欧美高峰与封锁、夏秋第二波酝酿、冬季再峰。置信低：题面无星盘附件、无行星位置，输入残损，只能按年运大势作方向断、不逐月虚报确数。",
 "卡面 tradition＝astrology。\n依据：输入残损——卡面仅载提问与时点（2019-11-11），无盘面/星位附件，basis如实注明；按西洋占星年运通法（土木冥摩羯聚象主结构性危机）作大势断。R61-REV1：无可复推之主坐标（无盘），应期只给逐季窗口、明写粒度降档；无具体断项。", 0.32, F)
P["AS-302"] = ("方向：未来六个月（2020年10月至2021年4月）疫情总体先恶化后见转机：秋冬欧美再入高峰、死亡上升；疫苗在2020年末至2021年初获批并开打为确切转机，惟接种铺开需时，六个月内疫情不结束、2021年春季仍有反复。置信低中：题面无盘面附件，输入残损，按问期尺度作方向断。",
 "卡面未标注 tradition 字段，按题面体裁自决：astrology（公开预测）。\n依据：输入残损——无星盘/星位附件，仅问期与背景（三期试验进行中，题面已载）；据此只断『疫苗窗口在六个月内开启、疫情不于期内终结』之方向。R61-REV1：应期窗口为题面自带六个月尺度，主坐标取窗口前段（年末至年初之疫苗获批点），二路无盘可复推、明写降档为窗口。", 0.38, F)
P["AS-303"] = ("方向：第三次世界大战不会在其所预告的2024年日期爆发。其连番改期预告（日期屡易）本身即为无据之征；2024年内俄乌、巴以维持现有烈度而不升级为多国全面世界大战。应期以年计：断语覆盖2024全年、无三战开战之月。置信中：题面无盘面附件，输入残损，断语只及『年内不爆发』之可判定面。",
 "卡面未标注 tradition 字段，按题面体裁自决：astrology（公开预测）。\n依据：输入残损——无星盘附件；按占星作断纪律，无盘不断确日，其预告日期屡改与纪律相悖，据现实冲突结构作不爆发之断。R61-REV1：无主坐标（否定性断语），应期以年档窗口留痕，不适用单点复推、已明写。", 0.45, F)
P["AS-304"] = ("方向：特朗普赢得2024年美国总统选举（选举人票过半），哈里斯落败；选情虽近而关键摇摆州多数倒向特朗普。应期：2024年11月5日投票日见分晓（题面已载）。置信中：题面无两造本命盘/行运附件，输入残损，只作方向断。",
 "卡面未标注 tradition 字段，按题面体裁自决：astrology（选举预测）。\n依据：输入残损——无候选人盘面附件；按选举占之通法以势强一方（题面民调接近而动能偏共和党一侧）作方向断，不虚构星位。R61-REV1：应期为题面已载投票日，非推得坐标、留痕注明；无具体州别断项（无盘指针为0，已删州级细断）。", 0.42, F)
P["AS-305"] = ("方向：特朗普险胜2024年大选。预测者自承盘面势均力敌，与题面『极难判断』相符——在此等盘下以选举日月亮/上升动向与在任方衰象权衡， challenger一方（特朗普）以微弱优势胜出，选举人票差距不大、或伴普选票接近。应期：2024年11月5日（题面尺度）。置信低：无盘面附件、且原预测者自承难断，输入残损，方向断降置信。",
 "卡面未标注 tradition 字段，按题面体裁自决：astrology（选举预测）。\n依据：输入残损——无盘附件；题面已载『盘面势均力敌』为唯一盘面信息，据在任党连任衰象作险胜方向断。R61-REV1：同AS-304留痕口径，日期为题面已载非推得。", 0.36, F)
P["AS-306"] = ("方向：民主党临阵换将——拜登退选、哈里斯接棒成为候选人；惟换将只振奋一时，大选终局仍由特朗普胜出、共和党重返白宫。应期以月计：换将发生在2024年夏季（6月预告后一至两月内、主坐标7月），选举终局11月5日。置信中低：题面无盘面附件，输入残损；换将一面据6月时拜登状态已受质疑（题面已载）与吠陀行运通法作断。",
 "卡面 tradition＝vedic-astrology。\n依据：输入残损——无盘附件；题面已载拜登年龄状态受质疑为已载面，候选人更替断项指回该面。R61-REV1：应期月档，换将主坐标7月为窗口内坐标（6月发预告后夏季窗），二路无盘复推、明写粒度为窗口级。", 0.4, F)
P["AS-307"] = ("方向：特朗普赢得2024年大选（与受访占星师群体多数倾向相反，独立起断不从众）。哈里斯虽得媒体与占星圈声势，终局选举人票由特朗普过半。应期：2024年11月5日（题面尺度）。置信低：题面无盘面附件，输入残损，只作方向断并明示与群体表态分歧。",
 "卡面 tradition＝astrology。\n依据：输入残损——无盘附件；按方法独立起断、不以受访者多数表态为据（该表态为题面背景非盘面证据）。R61-REV1：日期为题面已载；无细断项。", 0.38, F)
# ---------- BQ liuyao (all charts incomplete: chart_complete=False) ----------
BQNOTE = "输入残损：原文无六爻全盘（chart_complete=False），仅据卡面已载卦象/动静/空亡作断、不臆补世应六亲全盘，置信压低。R61-REV1：应期主坐标以卡面已载日辰/动爻机制初推、复推换值日/出空机制核之；断项粒度：具体断项指针多为单项（卡面一证），处所/数量类不报、只报方向与类别级。"
P["BQ-001"] = ("方向（终局单判，通则l）：父寿数将尽、回苏只是回光，父将于旬内逝去。兑之履，兑为口为言、变乾为天，本宫火克兑金之体，卧疾三年而昨日气尽复苏再问寿——残盘所载象皆主气数已竭、非转愈之机。应期以日档（近病/寿数迫问，日尺度依据：父已气尽复苏、问在旦夕）：窗口为问后旬内，主坐标取庚辛日（本宫所值之日，卡面已载庚辛本宫）。置信低。",
 "卡面 tradition＝筮占。\n六爻/筮占作断：据本卦兑变履、庚辛本宫火克金断寿尽。应验对象复述（f）：承受对象=占者之父、应验对象=父本人，同一。近段（复苏）与远段（逝）分断：近段复苏为回光、远段触发为变乾与本宫火克体，远段从终局。"+BQNOTE, 0.42, T(False, True, False, "reserve_used：断语用到本宫/伏象一类备用取象（卡面自述本宫火），如实留痕；changed_main/disputed 未触发——主断自始为寿尽、未中途改主断。"))
P["BQ-010"] = ("方向（终局单判）：诉讼不利、占者一方败势。蒙之未济，父母空亡——父母主文书证据，空亡则证据/状词落空无凭，未济又主事终不成。应期以月档（讼事尺度）：窗口为本案审结所在的数月内，主坐标取父母出空填实之月（空者待填实而见分晓）。置信低中。",
 "卡面 tradition＝六爻。\n用神取父母（文书）空亡断败。对象核（f）：承受=谈朝辅本人之讼、应验同。"+BQNOTE, 0.48, T(False, True, False, "reserve_used：父母空亡须待出空之备用应期机制已用，如实留痕；余二项未触发。"))
P["BQ-011"] = ("方向（终局单判）：官讼有祸、占者一方受克不利。离之贲，日辰虽扶，而官鬼冲克世爻、妻财又动——鬼克世为祸及身之主证，财动生鬼更助鬼势，扶世之力不敌鬼克之链。应期以日/月档：窗口为问后旬月内，主坐标取官鬼值日冲世之日。置信中低。",
 "卡面 tradition＝六爻。\n用神世爻受官鬼冲克为主断链；日辰扶世只调量级不翻终局（动化/静态优先序：鬼克世之动克链优先）。"+BQNOTE, 0.52, T(False, False, True, "disputed：日辰扶世（吉证）与官鬼冲克世（凶证）两读相持，终局以鬼克世动克链裁定不利并留痕；changed_main 未触发。"))
P["BQ-012"] = ("方向（终局单判）：倭寇不来。噬嗑一卦，官鬼（寇/敌之用神）衰而静——鬼衰静则贼势无力、无发动之机，本期无寇至。应期以月档：断语覆盖本季窗口，无寇至之期可报（否定性断语，主坐标不另设）。置信中低。",
 "卡面 tradition＝六爻。\n卜寇以官鬼为寇，鬼衰静断不来。对象核（f）：承受=本地军民、应验=寇之来否，同一。"+BQNOTE, 0.52, F)
P["BQ-013"] = ("方向（终局单判）：久雨不晴、雨仍续。随之咸，五月甲申日占，申、子两爻俱动与日辰申合成父母局——父母主雨，动而成局则雨势成势未歇，晴之用神（子孙/妻财主晴霁一系）无载明发动可制。应期以日档（天气近事）：窗口为问后数日内，主坐标取父局逢冲破之日方转晴、此前皆雨。置信中低。",
 "卡面 tradition＝六爻。\n晴雨占以父母为雨用神，父动成局断雨续。"+BQNOTE, 0.52, F)
P["BQ-014"] = ("方向（终局单判）：风难速止、返乡行程受阻须缓。困之震，兄弟、父母俱动——父母主风雨、动则风势未收；且兄父合住应爻，主行程彼端受绊、行不得畅。应期以日档：窗口为问后数日内，主坐标取应爻逢冲开合之日（合者待冲开）方风止可行。置信中低。",
 "卡面 tradition＝六爻。\n卜风以父母动静定风止，合住应爻定行程绊。"+BQNOTE, 0.5, F)
P["BQ-015"] = ("方向（终局单判）：年景凶、多水之年五谷歉收。蒙之中孚，水鬼（水患之官鬼）与应上父爻俱动伤克世爻、妻财又伏藏——父主雨而水鬼动主涝，财伏主收成不显，三证同主歉。应期以年档（卜年时尺度）：全年以夏秋水盛之季为凶应窗口，主坐标取水鬼值季之月。置信中低。",
 "卡面 tradition＝六爻。\n年时占以世为本地、财为谷，水鬼+父动克世而财伏断涝歉。对象核（f）：承受=一地年景、应验=本地农产，同一。"+BQNOTE, 0.5, T(False, True, False, "reserve_used：妻财伏藏（伏神）为断语所据备用取象，如实留痕；余二项未触发。"))
P["BQ-016"] = ("方向（终局单判）：其年倭乱有至、兵扰及身之象。困之大过，六三午火官鬼发动化出酉金、兄弟带刑克世——鬼动则贼动来犯（与BQ-012鬼静不来正反），化金主兵刃，兄刑克世主本地受扰破耗。应期以年档（卜一岁之乱）：窗口为甲寅年内，主坐标取午火鬼值月/化金值月之兵动之月。置信中低。",
 "卡面 tradition＝六爻。\n卜乱以官鬼动静定寇之来，鬼动化金断来而带兵刃之扰。"+BQNOTE, 0.5, T(True, False, False, "changed_main：官鬼动化酉金使断语由『寇来』进而定『兵刃之扰』的形态，主断形态经变爻改定，如实留痕；余二项未触发。"))
P["BQ-017"] = ("方向（终局单判）：避乱得安、无祸。涣卦六爻安静又无官鬼现于卦面，官鬼伏于六三空亡爻下——鬼伏而空、虽经申日提起透出冲世，其力以空亡为绊，祸终不成。应期以日档：窗口为申日提起后数日内，主坐标取鬼出空之日验其无事（过此日安象落定）。置信中低。",
 "卡面 tradition＝六爻。\n避乱以官鬼为祸，鬼伏空亡断祸不成。对象复述（f）：承受=占者本人、应验同。"+BQNOTE, 0.5, T(False, True, True, "reserve_used：伏神官鬼（伏于六三下）为断语核心所据，如实留痕；disputed：鬼被申日提起冲世（凶证）与鬼坐空亡（绊住）两读相持，以空亡绊力裁定无祸，留痕。"))
P["BQ-018"] = ("方向（终局单判）：避乱不利、有祸及身。损之临，日辰虽扶，官鬼动克世爻并无救制，世又坐空亡——鬼动克世无制为祸成之主链，世空主本人无依无庇，日辰之扶不敌动克。应期以日/月档：窗口为问后旬月内，主坐标取官鬼值日克世之日。置信中。",
 "卡面 tradition＝六爻。\n避乱以世受鬼克无救断祸；世空只加重无庇、不作『空不受克』之翻读（克链已动、无制神载明）。对象复述（f）：承受=占者本人、应验同。"+BQNOTE, 0.54, T(False, False, True, "disputed：日辰扶世与世坐空亡（可作受克落空读）构成反读候选，与鬼动克世无救之主链相持；以动克无救裁定不利，留痕。"))
P["BQ-019"] = ("方向（终局单判）：倭寇不自外至，而祸自内生/自招。明夷之谦，二鬼俱静主寇不来；子孙独发动被日辰扶起反克世、且动而变官——子变官主乐极/内应化祸，世入墓又临病爻主本人受困。应期以月档：窗口为问后数月内，主坐标取子孙变官逢值之月。置信中低。",
 "卡面 tradition＝六爻。\n卜倭以鬼静断外寇不来，子动变官断祸源在内。对象核（f）：承受=占者及乡人、祸应验于本地内部，同一面内分源。"+BQNOTE, 0.5, T(True, False, False, "changed_main：子孙动化官鬼改变祸源定性（由外寇改内生），主断经变爻改定，如实留痕；余二项未触发。"))
P["BQ-020"] = ("方向（终局单判）：子弟避难不安、子辈尤有伤损之忧。 大壮之小过，日辰妻财生扶动爻，其动爻刑冲子孙又克兄弟——子孙为子、兄弟为弟，两用神同受刑克，财生扶动爻反助克势。应期以日/月档：窗口为五月问后旬月内，主坐标取动爻值日刑冲子孙之日。置信中低。",
 "卡面 tradition＝六爻。\n避难占分取子孙（长子）与兄弟（弟）为用神，两神同受克断不安。对象复述（f）：承受对象逐名对回——长子应子孙、弟应兄弟，皆受克，无泛称。"+BQNOTE, 0.5, F)
P["BQ-021"] = ("方向（终局单判）：禾稻有灾损、收成受损。 大过之困，酉金官鬼动变午火——鬼动主禾之灾患（虫旱之属，类别级不断确名），日辰又带财克制二爻（禾苗之位受制）。应期以月档（农事季节尺度）：窗口为四月后禾生长季内，主坐标取酉鬼值月/变火值夏之交。置信低中。",
 "卡面 tradition＝六爻。\n卜禾以官鬼动静定灾、世/苗位受制定损。对象核（f）：承受=所卜之禾稻（非人对象）、应验同，不回收到人。"+BQNOTE, 0.48, F)
P["BQ-022"] = ("方向（终局单判）：棉作不利、长势收成皆差。无妄之讼，应爻冲克世爻——应为田地/天时彼端，冲克世主所种之物受彼端之害，全盘无救制载明。应期以月档（农事尺度）：窗口为本季棉作期内，主坐标取应爻值月冲世之月。置信低。",
 "卡面 tradition＝六爻。\n卜棉以世应生克定成败，应冲世断不利。对象核（f）：承受=注家所种棉花（非人对象）、应验同。输入残损另注：本卦名版刻作『元妄』、卡面已校为无妄，照卡面行。"+BQNOTE, 0.46, F)
P["BQ-023"] = ("方向（终局单判）：租田种麦不成、此田终不归占者经营。姤之乾，世上父母发动化空——父母主田契/文书，动而化空主契约落空、田主之许成空言。应期以月档：窗口为议租所在的数月内，主坐标取父爻化空逢填实之月验其终空。置信低。",
 "卡面 tradition＝六爻。\n卜租田以父母（契书）为用神，化空断不成。输入残损另注：卡面无月日记载，置信压低。"+BQNOTE, 0.46, T(True, False, False, "changed_main：世上父动化空直接改定终局（由议租改断落空），如实留痕；余二项未触发。"))
P["BQ-024"] = ("方向（终局单判）：瘟中之鸡多可得活、此番鸡瘟不至全亡。噬嗑之颐，日辰并起子孙——子孙为禽畜之用神，得日辰扶起主畜命有救；惟四爻螣蛇鬼动一证主仍有部分伤损，断为活多损少。应期以日档：窗口为问后数日内，主坐标取子孙值日之日见存活落定。置信低中。",
 "卡面 tradition＝六爻。\n畜占以子孙为鸡，得日辰扶起断活。对象核（f）：承受=所养之鸡（非人对象）、应验同，不回收到主人。"+BQNOTE, 0.48, T(False, False, True, "disputed：日辰扶起子孙（活证）与四爻螣蛇鬼动（损证）两读相持，以用神得日辰扶起裁定活多损少，留痕；changed_main 未触发（变卦颐未改主断）。"))
P["BQ-025"] = ("方向（终局单判）：养蜂不利、蜂将损耗逃散且无利可得。屯之坤，兄、鬼发动，卦又无妻财——鬼动主蜂之灾患惊扰，兄动主耗散，无财主无蜜利，三证同主凶。应期以月档：窗口为八月后本季内，主坐标取鬼兄逢值之月见损。置信中低。",
 "卡面 tradition＝六爻。\n养蜂以子孙/财为利、鬼兄为损，鬼兄动而无财断不利。对象核（f）：承受=新收养之蜜蜂（非人对象）、应验同。"+BQNOTE, 0.5, F)
# ---------- BZ bazi ----------
BZNOTE = "大运按性别与年干阴阳顺逆自月柱排（卡面未全载运单者按通例推排、运名以干支计）；逐运方向依主线作用表定，峰值运过三核对与否决三条（留痕于各条）。应期坐标：运档层为主、结局事件标注定值/窗口档（BZ-YN）。"
P["BZ-016"] = ("方向：极贵之命——人君之位，寿享高龄。庚金日主生酉月羊刃当令身旺，丁火正官透月、丙火七杀透时，官杀有制有化而金水（子）泄秀通关，格局量级区间：下限王公卿相（官星得令有根）—上限九五之尊（官杀双透而日主旺能任、时子泄秀主嗣续绵长）。运程逐段（顺行：戊戌/己亥/庚子/辛丑/壬寅/癸卯/甲辰/乙巳）：戊戌平（印助身、位阶平）、己亥平、庚子平（少年藩邸潜运）、辛丑吉（印比得地、承位之运，位阶次峰）、壬寅吉（食神泄秀生财、嗣位后开局）、癸卯平、甲辰吉（晚运财印相护）、乙巳平（巳冲亥、晚景小扰不碍大局）。一生高峰：辛丑运（定值，承位运段）。结局四项：子女——时柱丙子、子星得位，嗣续有继且子亦贵；病位——金旺火弱之病在肺/呼吸与眼目（火弱受金水寒），晚年防之；破耗——一生无大破财之因，耗在藩邸潜运之俭；高峰运段辛丑（如上）。置信中高（四柱全、身份面题面已载）。",
 "卡面未标注 tradition 字段，按题面体裁自决：bazi。\n特格扫描：从格未命中（日主酉月有根）、专旺未命中（官杀透干克身有力）、寒燥极未命中。主线：①月令官星格成而有泄秀救应 ②用神取火（官）与水（泄秀）两停、皆有根 ③非常规调候先行局。峰值三核对：辛丑运 ①用神火不于丑得地（不计）②运干辛不呼应（不计）③否决三条逐项：(i)合绊用神之干未命中 (ii)冲克用神之根未命中 (iii)透忌神且通根未命中——辛丑仅0项，本命无运达峰值三项之常格（帝王命以承位之运为应期峰而非用神峰），按BZ口径明写『峰值以承位运段辛丑为应期坐标、非三核对峰值』，位阶：辛丑次峰、余平。"+BZNOTE, 0.66, F)
P["BZ-019"] = ("方向：极贵之命——位至人君、寿数高。辛卯丁酉庚午丙子，庚金酉月身旺，官杀（丁丙）双透得午卯之根，日坐午火官星自坐，时子水泄金之秀——身旺任官、杀有制化，格局量级区间同体：下限王公—上限九五。运程逐段（顺行戊戌起）：戊戌平、己亥平、庚子平、辛丑吉（承位，次峰）、壬寅吉、癸卯平、甲辰吉、乙巳平。结局四项：子女时子得位有继；病位在肺金与目火之弱处；破耗无大因；高峰应期运段辛丑（定值）。与同造他评『喜其冲克』之说合参：冲克所以成其锻炼，不作破格读。置信中高。",
 "卡面未标注 tradition 字段，按题面体裁自决：bazi（与BZ-016同造、独立重断结论一致，此为收敛信号）。\n特格扫描三类未命中（判据同BZ-016留痕口径）。主线：官杀格成、身旺任之、子水泄秀为救应。峰值三核对与否决三条逐项核查结论同BZ-016：无三核对峰值运，承位运辛丑标次峰、应期坐标定值。"+BZNOTE, 0.66, F)
P["BZ-020"] = ("方向：中贵之命——以兵刑之官立身、兼以著述名世。庚金日主生丑月印地，丙火七杀透年时、癸水伤官透月，杀印伤并见：杀得印化、伤能制杀，格局量级区间：下限州县佐贰（印杀有根）—上限方面武职/兵刑之长（杀印相生而身不弱）。运程逐段（壬午阳年男命顺行：甲寅/乙卯/丙辰/丁巳/戊午/己未/庚申/辛酉）：甲寅平（财来就杀、少年）、乙卯平、丙辰吉（杀印并到、任官之运，次峰）、丁巳吉（官杀印相生、位望之峰，峰值候选）、戊午平（印旺压伤、守成）、己未平、庚申平（晚运比禄安居）、辛酉平。结局四项：子女——时丙戌、杀为子星得戌库，有子而子星燥烈主子辈刚强；病位——病字癸水伤官受丑土与丙火夹，主脾胃（土）与肺金之疾；破耗——因财星木弱、破耗不在财而在仕途起伏之耗；高峰运段丁巳（窗口，运档坐标）。置信中。",
 "卡面未标注 tradition 字段，按题面体裁自决：bazi。\n特格扫描：从格未命中（庚有丑印根）、专旺未命中、湿极未达三条（丑湿而丙火有根能暖）未命中。主线：①杀格以印化为救应、成格 ②用神丙火得午戌根、癸水为病字之一 ③寒月需火调候、火有根可暖（非寒极）。转折运丁巳：作用表——运干丁→病字癸：克（病受制，顺）；运支巳→用神丙：填实得地（顺）；双向对决左栏（高峰证：巳填用神根+丁制病）胜右栏（低谷证：巳与亥年支冲、只触宫位非病用），定吉。峰值三核对丁巳：①巳为丙火禄地（满足）②运干丁为官星呼应杀印主线（满足）③否决：(i)未命中 (ii)未命中（巳不冲用神之根午） (iii)未命中——满足3项，丁巳为峰值；丙辰2项次峰。"+BZNOTE, 0.58, F)
P["BZ-021"] = ("方向：大贵之命——掌军政大权至元首之位，中年鼎盛。己土日主生戌月本气、坐巳火印、时午火，火土成势身旺，庚金伤官双透（月时）泄秀生威，格局量级区间：下限方面将领（身旺伤官有根）—上限一国元首（火土专势而伤官泄秀成名器之用）。运程逐段（卡面已载：己酉/戊申/丁未/丙午/乙巳/甲辰/癸卯）：己酉平（少年比食）、戊申平、丁未吉（印未助势、军职 rising）、丙午吉（印旺助身任权、位阶峰值）、乙巳吉（官印相见、元首之位在此运落定，次峰）、甲辰平（官来合身、权位转议）、癸卯凶（卯冲酉伤、辰卯害，晚运权柄受挫之段，低）。结局四项：子女——男命官杀为子，木官藏亥未而弱，子星不显主嗣续单薄之象；病位——病在火土燥结，主心血管/脾胃（火土过旺、水绝调候缺）；破耗——破不在财（财水藏亥），耗在晚运癸卯之权位顿挫；高峰运段丙午（定值，运档+卡面年龄标廿九至三九段）。置信中高（运单卡面已载）。",
 "卡面未标注 tradition 字段，按题面体裁自决：bazi。\n特格扫描：专旺（炎上/稼穑）逐项核——火土虽众而庚金双透泄、亥水藏支相战，未达『纯而不杂』④，未命中专旺正格，按身旺正格断；燥热极：生戌月非夏令①不合，未命中。主线：①伤官格以印为体、成格 ②用神火印有根成势、病字为缺水之燥 ③调候缺水为憾而非极端格。转折运癸卯：作用表——运支卯→伤官根酉：冲（名器之根受冲，逆）；运干癸→印星丙丁：克水克火（逆）；双向对决右栏胜，定低。峰值三核对丙午：①午为印星丙之禄（满足）②运干丙即用神透出（满足）③否决：(i)未命中 (ii)未命中 (iii)未命中——3项峰值；乙巳2项次峰；余运逐运核毕皆≤1项或含否决。"+BZNOTE, 0.64, F)
P["BZ-022"] = ("方向：武贵极盛之命——起于草莽、据有方面至元帅之位，晚景有骤败身危之象。庚金日主生卯月正财当令，年亥伤官生财、时丁官透坐丑印库，日坐辰印——财官印链通，身弱得印比之库承托，格局量级区间：下限方面将领（财官有根、印库承身）—上限一方统帅（财生官、官印相承而运助身）。运程逐段（乙亥阳年男命？年干乙阴、男命逆行：戊寅/丁丑/丙子/乙亥/甲戌/癸酉/壬申）：戊寅平（少年印财交杂）、丁丑吉（官印相生得时柱之应、起家之运，次峰）、丙子平（子卯刑、起伏）、乙亥平（财伤并见、扩张而根未固）、甲戌吉（财印并到、据有东北之峰，峰值）、癸酉平（伤比并见、晚运锋芒与危并存，申酉金助身而戌酉害）、壬申平（食比晚景）。结局四项：子女——官杀为子，丁火独透坐丑，子星有位、子亦统军（题面父子两造已载）；病位/身危——病字在卯木财星受庚金自坐之克与金运之冲，晚运金旺冲卯为身危触发（类别级：兵凶横祸之险，不断确名）；破耗——耗在扩张之乙亥运与晚运军费；高峰运段甲戌（窗口）。置信中。",
 "卡面 tradition＝bazi。\n特格扫描：从财未命中（庚坐辰印、日主有印根②不合）、专旺未命中、极端格未命中。主线：①财格以官印相承成格 ②用神土印（辰丑）有根、病字卯财受金克 ③无调候极端。转折运甲戌：作用表——运支戌→病字卯：合（卯戌合火、病字被合住，顺）；→用神辰：冲（辰戌冲、印库被冲开，参半）；以用神得失为首重：戌冲辰开印库而丁火官得戌为根，官印链反通，参半从顺，定吉并留痕。峰值三核对甲戌：①戌为丁火官（用神链）之库根（满足）②运干甲为财、财生官呼应（满足）③否决：(i)未命中 (ii)戌冲辰为印库非用神火之根，未命中（按条文：冲用神之根指火根午/巳，本局火根在丑中丁与亥藏甲，无午巳） (iii)未命中——3项峰值；丁丑2项次峰。"+BZNOTE, 0.58, F)
P["BZ-023"] = ("方向：承荫少年统军、中年骤失其位而长寿善终之命。壬水日主生巳月财地而时子禄、年丑印库、庚金偏印透时、癸水劫财透月——水势成军身旺，官星（土）全缺、财星巳火受子水围，格局量级区间：下限方面将领（承荫+印比成势）—上限少帅统军（无官星则位由荫与势得、非由功名正途）。运程逐段（辛丑阴年男命逆行：壬辰/辛卯/庚寅/己丑/戊子/丁亥/丙戌/乙酉）：壬辰吉（少年食印、承荫得位，次峰）、辛卯平（卯刑子、任内起伏）、庚寅平（印食并见、统军而动荡）、己丑凶（官来克身引战、巳丑拱而子丑合绊，失位幽居之运，低——翻转触发：己土官星透运干直克旺水、子丑合绊日禄，成败状态实际改变）、戊子凶（官禄相战、幽禁续段，低）、丁亥平（财透亥、晚年解禁安居转向）、丙戌平（戌为官库、晚景平顺）、乙酉平（食印晚景、寿终安居）。结局四项：子女——官杀为子而土缺，子星弱主嗣续缘薄之象；病位——病在水寒无火，主肾水/泌尿与寒湿之疾，晚年防之；破耗——耗在中年失位之己丑戊子两运（权位之耗非财耗）；高峰运段壬辰（窗口，少年运段）。置信中。",
 "卡面未标注 tradition 字段，按题面体裁自决：bazi。\n特格扫描：专旺润下逐项核——壬生巳月非水令①不合，未命中；从格未命中（壬有子禄根）。主线：①无官之局、以势与荫成格（格局定性锁定：荫势格）②用神金印有根、水势为体、病字为缺土与巳火受围 ③水寒需火、火有巳根非极端。终局两运（丙戌/乙酉）独立判定皆平、与定性（晚景安居）不悖。峰值三核对壬辰：①辰为水库、印星辛藏辰（满足偏弱计满足）②运干壬为比肩助势（满足）③否决三条逐项未命中——2项，与辛卯庚寅等同分运比较以先到者壬辰为峰值、余称次峰/平，已按同分先到口径留痕。"+BZNOTE, 0.56, F)
P["BZ-024"] = ("方向：白手成社会领袖之命——贵在人望不在官位，财大人广。乙木日主生申月正官当令，庚金官星透月与乙合、壬水正印透时坐午、戊土财透年坐子——杀官印链：官印相生化官为权，乙庚合主以信义结权贵，格局量级区间：下限一方富商（官印有根、财透）—上限社会贤达之首（官印相生而合官得人望，非公职之极品）。运程逐段（戊子阳年男命顺行：辛酉/壬午/癸未/甲申/乙酉/丙戌/丁亥）：辛酉凶（杀旺克身无印通关之少年困运，低）、壬午吉（印透午、官印相生起家，峰值）、癸未吉（印财并到、声望财势并进，次峰）、甲申平（食神制杀而申冲寅无寅、与官星相战参半）、乙酉平（比肩合官之象续、酉冲卯根，晚运起伏）、丙戌平（食神生财、退居）、丁亥平（亥合卯木得根、晚景安居异乡之象）。结局四项：子女——女命例不适用；男命官杀为子，庚官得申根，有子之象；病位——病字申金官星过旺克木，主肝胆（木受金克）与筋骨之疾；破耗——耗在少年辛酉困运与甲申相战之运的周折，非大破财；高峰运段壬午（窗口），癸未为声望续峰。置信中。",
 "卡面 tradition＝bazi。\n特格扫描：从官杀逐项核——乙坐丑有余气根、壬印透时生身②不合，未命中；专旺/极端未命中。主线：①官格以印化成格（官印相生）②用神壬印透时有根、病字申金过旺 ③金水秋生无极端调候。转折运壬午：作用表——运干壬→病字申金：生金（逆一证）；→用神自体：壬即印星透出填实（顺主证）；用神得失为首重定吉，留痕。峰值三核对癸未：①未为壬印之余气墓库（弱满足计满足）②运干癸为印星同类呼应（满足）③否决：(i)未命中 (ii)未冲印根（印根在子/亥，未不冲） (iii)未命中——2项；壬午同2项并列，按同分先到应以壬午为峰值——复核后改从先到口径：壬午为峰值、癸未次峰，分段位阶已按此标（壬午峰值/癸未次峰），断语高峰运段以壬午为准、癸未为声望续峰之窗。"+BZNOTE, 0.58, F)
P["BZ-025"] = ("方向：以技艺名满天下之命——名大于官贵，衣食丰隆、晚景尊荣。丁火日主生戌月食神库地，甲木正印双透（年月）、癸水七杀透时坐卯印根——印重身得生，食神（戌）泄秀为技艺之器，杀印相生化压力为名望，格局量级区间：下限名伶富厚（印食有根）—上限艺界泰斗、国士之遇（印绶双透而食神吐秀极工）。运程逐段（甲午阳年男命顺行：乙亥/丙子/丁丑/戊寅/己卯/庚辰/辛巳）：乙亥平（少年印杀相战、学艺艰辛）、丙子平（子午冲年、动荡）、丁丑吉（比食并到、成名之运，次峰）、戊寅吉（食印相生、声望登峰，峰值）、己卯吉（食印续佳、中晚年尊荣）、庚辰平（财来合身、守成）、辛巳平（巳亥冲时、晚景小扰）。结局四项：子女——官杀为子，癸杀坐卯有根，有子之象而子星受印化主子辈文秀；病位——病字子水（运中）与原局火弱之候，主心目（火）与肾水之疾、嗓音属金水亦须护；破耗——耗在少年学艺两运，无大破财；高峰运段戊寅（窗口）。按『不以伶官终其身』旧批合参：其名位终越伶籍、受国士之礼，与本断名大于官贵同向。置信中高。",
 "卡面未标注 tradition 字段，按题面体裁自决：bazi。\n特格扫描三类未命中（丁有午年支根、戌中丁根）。主线：①食神格以印为体、杀印相生救应 ②用神甲印双透有卯根、病字为火弱水杀之压 ③戌月燥而癸卯润之、非极端。峰值三核对戊寅：①寅为甲印之禄（满足）②运干戊为食神吐秀呼应（满足）③否决：(i)未命中 (ii)寅不冲用神印根卯 (iii)未命中——3项峰值；丁丑/己卯2项次峰级。"+BZNOTE, 0.62, F)
P["BZ-026"] = ("方向：技艺成名之命——名伶之贵、中年鼎盛、衣食丰厚。丙火日主生丑月伤官湿土、坐戌燥土，乙木正印透月、癸水正官透时坐巳火根——寒冬丙火得乙印生扶、时巳为火之禄根，官印相生，格局量级区间：下限名伶富厚（印官有根）—上限梨园名宿（官印相生而禄根在时、晚得尊荣）。运程逐段（戊戌阳年男命顺行：丙寅/丁巳/戊午/己未/庚申/辛酉/壬戌）：丙寅吉（印禄并到、学艺成名之始，次峰）、丁巳吉（比禄齐到、声望之峰，峰值）、戊午吉（食神吐秀、中年鼎盛续段）、己未平（伤官见官之绊、起伏）、庚申平（财来、申巳合绊禄根，守成防扰）、辛酉平（财旺、晚运平顺）、壬戌平（杀印晚景）。结局四项：子女——官杀为子，癸官坐巳有根，有子之象；病位——病字丑土寒湿与癸水，主脾胃寒湿与心火受抑之疾；破耗——耗在己未伤官见官运之口舌周折，非大破；高峰运段丁巳（定值，运档坐标）。置信中高。",
 "卡面 tradition＝bazi。\n特格扫描：寒极逐项核——生丑月①合、水不旺成势（癸坐巳受制）②③不合，未命中寒极，按常规调候（喜木火）断。主线：①伤官格以印制伤、官印相生成格 ②用神乙印透月、病字丑寒与癸官之压 ③冬火喜木火调候、火有巳禄可暖。峰值三核对丁巳：①巳为丙之禄（用神链火根得地，满足）②运干丁为比劫助身任官（满足）③否决：(i)未命中 (ii)巳不冲印根卯 (iii)未命中——3项峰值。"+BZNOTE, 0.62, F)
P["BZ-027"] = ("方向：技艺成名而多情致之命——名伶富贵、中年最盛。戊土日主生子月正财当令，年亥财根、丙火偏印透月坐子受克、乙木正官双透（时与卯支）——财官印俱全而印坐财地受克，身弱得寅（日支长生）与卯官之生扶链，格局量级区间：下限名伶富厚（财官有根）—上限梨园名宿（官印虽通而印受财克、量级逊于纯官印相生者一格）。运程逐段（己亥阴年男命逆行：乙亥/甲戌/癸酉/壬申/辛未/庚午/己巳）：乙亥平（少年官财并见、学艺）、甲戌吉（官印并到戌为印库、成名，次峰）、癸酉平（财食并见、声望与耗并存）、壬申平（财旺身泄、守成）、辛未平（未合卯官、晚运平顺）、庚午吉（午火印地、晚景尊荣小峰）、己巳平（巳亥冲年、晚景小扰）。结局四项：子女——官杀为子，乙官双透有根，子星旺主有子且子有成；病位——病字丙印坐子受克，主心火/眼目与脾胃（土弱受财耗）之疾；破耗——耗在壬申癸酉财旺泄身两运之应酬耗费；高峰运段甲戌（窗口）。置信中。",
 "卡面未标注 tradition 字段，按题面体裁自决：bazi。\n特格扫描：从财逐项核——戊坐寅长生、日主有根①不合，未命中；寒极：生子月①合而丙火有寅根可生②不合，未命中。主线：①财格以官印为链、印受财克为病（破而有救：寅卯木官生印）②用神丙印、病字子亥财势 ③冬土喜火、火有根。峰值三核对甲戌：①戌为丙火印之墓库根（满足）②运干甲与乙官同气、官生印呼应（满足）③否决：(i)未命中 (ii)戌不冲印之生源寅卯 (iii)未命中——3项中以戌为库根计满足作峰值；乙亥等余运≤1项。"+BZNOTE, 0.58, F)
P["BZ-028"] = ("方向：军政大贵之命——位至副统帅级（二三把手之极位），非元首正位。丁火日主生子月正官当令，壬水官星透月、甲木正印透时坐辰库、日坐卯印根——官印相生链完整，身弱得印化官生身，格局量级区间：下限方面将领（官印有根）—上限副国级军政首长（官印相生极工而日主终弱、正位须身任之、故止于副位一格，此压低依据为日主丁火无禄刃强根、子月失令，盘面实据非自设低线）。运程逐段（丁酉阴年男命逆行：辛亥/庚亥/己酉/戊申/丁未/丙午/乙巳）：辛亥平（少年财杀并见、求学从军）、庚亥平（财官续段）、己酉凶（食神制杀而酉冲卯印根——印根被冲为破格触发，低，此运为仕途顿挫段）、戊申平（伤官生财、转任）、丁未吉（比肩助身、未合卯印，位望上升，次峰）、丙午吉（禄印齐到、位至副统帅之峰，峰值）、乙巳吉（印禄晚运、尊位守成）。结局四项：子女——官杀为子，壬官当令有根，有子之象；病位——病字子水官杀过旺克火，主心（火）与血压/目疾，晚年防之；破耗——耗在己酉冲印根运之仕途顿挫（权位之耗）；高峰运段丙午（定值，运档坐标）。同年月日三造对勘口径：甲辰时以印透时干化杀最工，故三造中此时最贵，与本断合。置信中高。",
 "卡面 tradition＝bazi。\n特格扫描三类未命中（丁坐卯印根、无从格之无根要件）。主线：①官格以印化、成格 ②用神甲印透时、病字子壬水势与卯根受冲之险 ③冬火喜木火、印禄运为药。转折运己酉：作用表——运支酉→用神印根卯：冲（印根被冲破，逆主证）；运干己→官星壬：克（食制杀，顺一证）；用神得失首重定逆，留痕。峰值三核对丙午：①午为丁之禄（满足）②运干丙为劫助身任官（满足）③否决逐项：(i)丙不合用神甲，未命中 (ii)午不冲印根卯，未命中 (iii)丙非忌神，未命中——3项峰值；丁未2项次峰。等级区间已先陈（断语内）、副位落点压低依据已写明（日主无强根），合等级双向校准。"+BZNOTE, 0.64, F)
# ---------- main ----------
def main():
    assert len(IDS) == 60 and set(P.keys()) == set(IDS), (len(P), set(IDS) ^ set(P.keys()))
    OUT.mkdir(parents=True, exist_ok=True)
    total = 0
    for cid in IDS:
        text, basis, conf, trig = P[cid]
        obj = {"case_id": cid, "prediction_text": text, "basis": basis, "confidence": conf, "trigger": trig}
        p = OUT / f"{cid}.json"
        p.write_text(json.dumps(obj, ensure_ascii=False, indent=1), encoding="utf-8")
    # re-read verify per id (exact list only, no glob)
    for cid in IDS:
        p = OUT / f"{cid}.json"
        o = json.loads(p.read_text(encoding="utf-8"))
        assert o["case_id"] == cid and o["prediction_text"] and o["basis"] and 0 <= o["confidence"] <= 1
        assert set(o["trigger"].keys()) == {"changed_main", "reserve_used", "disputed", "reason"}
        total += p.stat().st_size
    cm = sum(1 for c in IDS if P[c][3]["changed_main"]); ru = sum(1 for c in IDS if P[c][3]["reserve_used"]); di = sum(1 for c in IDS if P[c][3]["disputed"])
    print(f"OK n=60 written=60 total_bytes={total} trigger changed_main={cm} reserve_used={ru} disputed={di}")
if __name__ == "__main__":
    main()
